namespace Campground.Shared.Privacy
{
    /// <summary>
    /// Strips secrets and personal data from anything that leaves the server (logs, support bundles, issue
    /// reports). Tokens use CleanStream's proven pattern; IPs and e-mail addresses are masked.
    /// </summary>
    internal static class Redactor
    {
        internal const string Redacted = "[redacted]";

        private const string Keys = "api_?key|access_?token|token|x-emby-token|x-mediabrowser-token|password|pw|pin|secret|refresh_?token|authorization";

        // A quoted value, which may hold spaces and escaped quotes: "password" : "a b", password="a b".
        private static readonly Regex Quoted = new(
            "(?i)(?<![a-z])(" + Keys + ")(\"\\s*:\\s*\"|=\")(?:[^\"\\\\]|\\\\.)*",
            RegexOptions.Compiled);

        // Authorization with a scheme: the scheme stays, the credential goes.
        private static readonly Regex AuthScheme = new(
            "(?i)(?<![a-z])(authorization\\s*[:=]\\s*(?:bearer|basic|negotiate|ntlm)\\s+)[^\\s\"\\\\]+",
            RegexOptions.Compiled);

        private static readonly Regex Tokens = new(
            "(?i)(?<![a-z])(" + Keys + ")(=(?:\\\\u0022|\")?|\"\\s*:\\s*\"?|\\\\u0022:\\\\u0022|:\\s*)(?!(?:bearer|basic|negotiate|ntlm)\\s)[^&\"\\s\\\\]+",
            RegexOptions.Compiled);

        private static readonly Regex EmbyAuth = new("(?i)(Token=\")[^\"]+(\")", RegexOptions.Compiled);
        private static readonly Regex Bearer = new("(?i)(Bearer\\s+)[A-Za-z0-9._~+/=-]+", RegexOptions.Compiled);
        private static readonly Regex Email = new(@"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", RegexOptions.Compiled);
        // ASCII digits only: \d also matches other scripts' digits, which int.Parse rejects. A full stop after
        // the address is the end of a sentence; a full stop and a digit is a longer dotted number.
        private static readonly Regex IPv4 = new(@"(?<![0-9])(?<![0-9]\.)([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})(?![0-9])(?!\.[0-9])", RegexOptions.Compiled);

        // Any run of hex groups with 2 to 7 colons, including "::" forms; IPAddress.TryParse decides if it is one.
        private static readonly Regex IPv6 = new(@"(?<![0-9A-Za-z:])[0-9A-Fa-f]{0,4}(?::[0-9A-Fa-f]{0,4}){2,7}(?![0-9A-Za-z:])", RegexOptions.Compiled);

        /// <summary>Redacts tokens, passwords, e-mail addresses; masks IPs (keeps private ranges' first two octets for support).</summary>
        internal static string Redact(string? text, bool maskAddresses = true)
        {
            if (string.IsNullOrEmpty(text))
            {
                return text ?? string.Empty;
            }

            var s = Quoted.Replace(text, m => m.Groups[1].Value + m.Groups[2].Value + Redacted);
            s = AuthScheme.Replace(s, m => m.Groups[1].Value + Redacted);
            s = Tokens.Replace(s, m => m.Groups[1].Value + m.Groups[2].Value + Redacted);
            s = EmbyAuth.Replace(s, m => m.Groups[1].Value + Redacted + m.Groups[2].Value);
            s = Bearer.Replace(s, m => m.Groups[1].Value + Redacted);
            s = Email.Replace(s, "[email]");
            if (maskAddresses)
            {
                s = IPv4.Replace(s, m => IsValidIPv4(m) ? MaskIPv4(m) : m.Value);
                s = IPv6.Replace(s, m => m.Value.Any(Uri.IsHexDigit) && IPAddress.TryParse(m.Value, out _) ? "[ipv6]" : m.Value);
            }

            return s;
        }

        private static bool IsValidIPv4(Match m) => Enumerable.Range(1, 4).All(i => int.Parse(m.Groups[i].Value) <= 255);

        private static string MaskIPv4(Match m)
        {
            var a = int.Parse(m.Groups[1].Value);
            var b = int.Parse(m.Groups[2].Value);
            var isPrivate = a == 10 || a == 127 || (a == 192 && b == 168) || (a == 172 && b >= 16 && b <= 31) || (a == 100 && b >= 64 && b <= 127);
            return isPrivate ? $"{a}.{b}.x.x" : "[ip]";
        }
    }

    /// <summary>
    /// Keyed hash of an IP address so rate limits and history can tell clients apart without storing the
    /// address. The key is per server (keys/ip-hash.key), so hashes can't be matched across servers.
    /// </summary>
    internal static class IpHasher
    {
        private static readonly Lazy<byte[]> Key = new(() => SecretBox.LoadOrCreateKey(Path.Combine(CampgroundPaths.Root, "keys", "ip-hash.key")));

        /// <summary>Hash with the server key.</summary>
        internal static string Hash(IPAddress? address) => address == null ? "none" : Hash(address, Key.Value);

        /// <summary>Hash with an explicit key (tests).</summary>
        internal static string Hash(IPAddress address, byte[] key)
        {
            var ip = address.IsIPv4MappedToIPv6 ? address.MapToIPv4() : address;
            var mac = HMACSHA256.HashData(key, ip.GetAddressBytes());
            return "ip:" + Convert.ToHexString(mac, 0, 12).ToLowerInvariant();
        }
    }

    /// <summary>Deletes old files: everything older than maxAge, and the oldest beyond maxFiles.</summary>
    internal static class Retention
    {
        internal static int Prune(string directory, string pattern, TimeSpan maxAge, int maxFiles, DateTime? now = null)
        {
            if (!Directory.Exists(directory))
            {
                return 0;
            }

            var cutoff = (now ?? DateTime.UtcNow) - maxAge;
            var files = new DirectoryInfo(directory).GetFiles(pattern).OrderByDescending(f => f.LastWriteTimeUtc).ToList();
            var removed = 0;
            for (var i = 0; i < files.Count; i++)
            {
                if (i >= maxFiles || files[i].LastWriteTimeUtc < cutoff)
                {
                    try
                    {
                        files[i].Delete();
                        removed++;
                    }
                    catch (IOException)
                    {
                    }
                    catch (UnauthorizedAccessException)
                    {
                    }
                }
            }

            return removed;
        }
    }

    /// <summary>
    /// A zip an admin can attach to an issue: each plugin adds named text sections; everything is redacted on
    /// the way in. Contains a manifest listing what's inside and that it was redacted.
    /// </summary>
    internal sealed class SupportBundle
    {
        private readonly SortedDictionary<string, string> _sections = new(StringComparer.Ordinal);

        /// <summary>Adds (or replaces) a section, redacted. Names become file names.</summary>
        internal SupportBundle Add(string name, string content)
        {
            var safe = Regex.Replace(name, @"[^A-Za-z0-9._-]", "_");
            _sections[safe.EndsWith(".txt", StringComparison.Ordinal) || safe.EndsWith(".json", StringComparison.Ordinal) ? safe : safe + ".txt"] = Redactor.Redact(content);
            return this;
        }

        /// <summary>Adds the tail of a log file (default last 512 KiB), redacted.</summary>
        internal SupportBundle AddLogTail(string name, string path, int maxBytes = 512 * 1024)
        {
            if (!File.Exists(path))
            {
                return Add(name, "(file not found)");
            }

            using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
            if (fs.Length > maxBytes)
            {
                fs.Seek(-maxBytes, SeekOrigin.End);
            }

            using var reader = new StreamReader(fs, Encoding.UTF8);
            return Add(name, reader.ReadToEnd());
        }

        /// <summary>The section names (for previews: show the admin what will be shared).</summary>
        internal IReadOnlyCollection<string> Sections => _sections.Keys;

        /// <summary>Writes the zip.</summary>
        internal byte[] ToZip()
        {
            using var ms = new MemoryStream();
            using (var zip = new ZipArchive(ms, ZipArchiveMode.Create, leaveOpen: true))
            {
                var manifest = new StringBuilder()
                    .AppendLine("Campground support bundle")
                    .AppendLine("Created (UTC): " + DateTime.UtcNow.ToString("u"))
                    .AppendLine("Shared library: " + Registry.CampgroundShared.Version)
                    .AppendLine("Redacted: tokens, passwords, PINs, e-mail addresses, IP addresses")
                    .AppendLine("Sections:");
                foreach (var name in _sections.Keys)
                {
                    manifest.AppendLine("  " + name);
                }

                Write(zip, "MANIFEST.txt", manifest.ToString());
                foreach (var (name, content) in _sections)
                {
                    Write(zip, name, content);
                }
            }

            return ms.ToArray();
        }

        private static void Write(ZipArchive zip, string name, string content)
        {
            var entry = zip.CreateEntry(name, CompressionLevel.Optimal);
            using var w = new StreamWriter(entry.Open(), new UTF8Encoding(false));
            w.Write(content);
        }
    }
